const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"></path></svg>`;
const btn=(label,action,cls='secondary',ico='',attrs='')=>`<button class="button ${cls}" data-action="${esc(action)}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
