const defaultState=()=>({schema:1,plan:{start:'2026-11-16',hours:9,region:'global',name:'Curtis'},completed:[],attempts:[],review:{},bookmarks:[],notes:{},logs:[],history:[],checklist:[],session:null,focus:null});
let state=defaultState(),storageOK=true,recoveryWarning=false,recoveryRaw=null;
try{const raw=localStorage.getItem('pmp-path-v1');if(raw){recoveryRaw=raw;const parsed=JSON.parse(raw);if(C.validBackup(parsed,bank,lessons)){state={...state,...parsed};recoveryRaw=null;if(state.session&&!C.validSession(state.session,bank))state.session=null;if(state.focus&&(!Number.isFinite(state.focus.remaining)||state.focus.remaining<0||state.focus.remaining>1500000||typeof state.focus.running!=='boolean'||(state.focus.running&&!Number.isFinite(state.focus.endAt))))state.focus=null;}else{recoveryWarning=true;localStorage.setItem('pmp-path-recovery',raw)}}}catch{if(recoveryRaw){recoveryWarning=true;try{localStorage.setItem('pmp-path-recovery',recoveryRaw)}catch{storageOK=false}}else storageOK=false}
let page=location.hash.slice(1)||'dashboard',lessonFilter='all',lessonSearch='',reviewFilter='due',openWeek=1,currentResult=null,flashIndex=0,flashBack=false,modalReturn=null;
const optionOrder=(se,id)=>{const v=se?.order?.[id];return Array.isArray(v)&&v.length===4&&new Set(v).size===4&&v.every(n=>Number.isInteger(n)&&n>=0&&n<4)?v:[0,1,2,3]},letter=(se,id,n)=>String.fromCharCode(65+optionOrder(se,id).indexOf(n));
const today=()=>C.localDate(),qById=id=>bank.find(q=>q.id===id),lById=id=>lessons.find(l=>l.id===id),isDone=id=>state.completed.includes(id),report=()=>C.stats(state.attempts,bank);
const titleMap={dashboard:'学习概览',plan:'学习计划',learn:'知识课堂',practice:'练习中心',review:'错题与收藏',progress:'学习报告',resources:'备考工具箱',settings:'计划与设置',quiz:'正在练习',result:'练习报告'};
const dateText=d=>d.replaceAll('-','.'),shortDate=d=>`${Number(d.slice(5,7))}月${Number(d.slice(8,10))}日`;
const pace=()=>C.weeksFor(state.plan.hours),target=()=>C.targetDate(state.plan),completedPct=()=>lessons.length?Math.round(state.completed.length/lessons.length*100):0;
const dueIds=()=>Object.entries(state.review).filter(([,r])=>r.due<=today()).map(([id])=>id);
const wrongIds=()=>Object.entries(state.review).filter(([,r])=>r.everWrong&&r.streak<2).map(([id])=>id);
const minuteTotal=()=>state.logs.reduce((sum,l)=>sum+l.minutes,0);
function save(){try{localStorage.setItem('pmp-path-v1',JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('浏览器无法保存，请及时在设置中导出备份。')}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function navigate(next){if(!titleMap[next])next='dashboard';page=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'})}
function activeStreak(){const dates=new Set(state.logs.map(l=>l.date));let d=today(),n=0;if(!dates.has(d))d=C.addDays(d,-1);while(dates.has(d)){n++;d=C.addDays(d,-1)}return n}
function render(){
 if(!titleMap[page])page='dashboard';
 const nav=[['dashboard','home','学习概览'],['plan','plan','学习计划'],['learn','book','知识课堂'],['practice','practice','练习中心'],['review','review','错题与收藏'],['progress','chart','学习报告']];
 $('#app').innerHTML=`<div class="screen-overlay" data-action="close-menu"></div><aside class="sidebar" aria-label="主导航"><a href="#dashboard" class="brand" data-page="dashboard"><span class="brand-mark">${icon('book')}</span><span><span class="brand-name">进阶<span>PMP</span></span><span class="brand-sub" style="display:block">YOUR NEXT CHAPTER</span></span></a><div class="nav-label">我的学习空间</div><nav class="nav">${nav.map(([id,i,label])=>`<button data-page="${id}" class="${page===id||(id==='practice'&&['quiz','result'].includes(page))?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${label}${id==='review'&&wrongIds().length?`<span class="count">${wrongIds().length}</span>`:''}</button>`).join('')}</nav><div class="nav-label" style="margin-top:24px">备考支持</div><nav class="nav"><button data-page="resources" class="${page==='resources'?'active':''}">${icon('flag')}备考工具箱</button><button data-page="settings" class="${page==='settings'?'active':''}">${icon('settings')}计划与设置</button></nav><div class="sidebar-bottom"><div class="sidebar-note"><div class="row">${icon('leaf')}<span style="font-size:11px;font-weight:500">稳稳地，一步一步来。</span></div><p>每天前进一点，<br>让今天的学习有迹可循。</p></div><div class="user"><span class="avatar">${esc((state.plan.name||'C').slice(0,1).toUpperCase())}</span><div><div class="user-name">${esc(state.plan.name||'我的学习空间')}</div><small>个人备考空间 · 本地保存</small></div><button class="icon-button" data-page="settings" aria-label="个人设置" style="margin-left:auto">${icon('settings')}</button></div></div></aside><div class="workspace"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="展开导航">${icon('menu')}</button><div class="breadcrumb"><span>我的学习空间</span>${icon('chevron')}<span>${titleMap[page]}</span></div><div class="top-tools"><button class="search-trigger" data-action="search" aria-label="搜索知识点、课程、题目">${icon('search')}<span>搜索知识点、课程、题目</span><kbd>⌘ K</kbd></button><span class="date-label">${new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'short'})}</span><button class="icon-button" data-action="focus" aria-label="打开专注计时">${icon('clock')}</button></div></header><main id="main" class="main" tabindex="-1">${!storageOK?`<div class="notice amber" style="margin-bottom:18px">${icon('info')}浏览器存储不可用。当前操作仅保留在本次页面中，请导出备份。</div>`:''}${recoveryWarning?`<div class="notice amber" style="margin-bottom:18px">${icon('info')}已有记录无法读取，已启动空白工作台。请先到设置下载原始存储，再恢复有效备份。</div>`:''}${renderPage()}<footer class="footer"><span>进阶 PMP · 把大目标，变成今天的小进步。</span><div class="row"><span>原创学习内容 · 非 PMI 官方产品</span><a href="https://github.com/curtisatiwatt/pmp" target="_blank" rel="noopener noreferrer">GitHub ${icon('external')}</a></div></footer></main></div>`;
 updateTimers();
}
function heading(title,subtitle,action=''){return `<div class="page-heading between"><div><h1>${title}</h1><p class="sub">${subtitle}</p></div>${action}</div>`}
function renderPage(){return ({dashboard:dashboard,plan:planPage,learn:learnPage,practice:practicePage,review:reviewPage,progress:progressPage,resources:resourcesPage,settings:settingsPage,quiz:quizPage,result:resultPage}[page]||dashboard)()}
const heroArt=()=>`<svg class="hero-art" viewBox="0 0 300 180" fill="none" aria-hidden="true"><circle cx="167" cy="86" r="70" fill="#e2ede3"/><circle cx="167" cy="86" r="53" stroke="#d1dfd3" stroke-dasharray="3 6"/><path d="M35 151L91 92l39 30 61-84 81 113" fill="#d3e3d5"/><path d="M119 151l72-113 81 113" fill="#bdd3c2"/><path d="M170 70l21-32 25 35-19-6-10 10-9-10z" fill="#f2f7ef"/><path d="M61 155c90-3 27-49 83-48 28 1 21-30 42-48" stroke="#779a80" stroke-width="2" stroke-dasharray="4 5"/><path d="M191 38V9" stroke="#427257" stroke-width="2"/><path d="M192 10l26 5-26 10z" fill="#428363"/><path d="M23 155h261" stroke="#a6c0ac" stroke-width="2" stroke-linecap="round"/><rect x="40" y="110" width="35" height="42" rx="5" fill="#f9fbf5" stroke="#c1d5c6" transform="rotate(-10 40 110)"/><path d="M49 121l4 4 8-11m-10 21 14-3m-12 11 11-2" stroke="#88a58c" stroke-width="2"/><circle cx="246" cy="49" r="15" fill="#f3eddb"/><path d="M242 49l3 3 6-7" stroke="#bba775" stroke-width="2"/><path d="M38 60l3 7 7 3-7 3-3 7-3-7-7-3 7-3z" fill="#b8ceba"/><circle cx="262" cy="115" r="4" fill="#c4d9c8"/></svg>`;
